diff --git a/src/test/script_standard_tests.cpp b/src/test/script_standard_tests.cpp
index 90b2a9856e..80bb7838ae 100644
--- a/src/test/script_standard_tests.cpp
+++ b/src/test/script_standard_tests.cpp
@@ -221,6 +221,21 @@ BOOST_AUTO_TEST_CASE(script_standard_Solver_failure)
     s << OP_1 << std::vector<unsigned char>{0xff, 0xff};
     BOOST_CHECK(!s.IsPayToAnchor());
     BOOST_CHECK_EQUAL(Solver(s, solutions), TxoutType::WITNESS_UNKNOWN);
+
+    // Single-byte mismatches for ANCHOR payload {0x4e, 0x73}
+    s.clear();
+    s << OP_1 << std::vector<unsigned char>{0x4e, 0x00};
+    BOOST_CHECK(!s.IsPayToAnchor());
+    BOOST_CHECK_EQUAL(Solver(s, solutions), TxoutType::WITNESS_UNKNOWN);
+
+    s.clear();
+    s << OP_1 << std::vector<unsigned char>{0x00, 0x73};
+    BOOST_CHECK(!s.IsPayToAnchor());
+    BOOST_CHECK_EQUAL(Solver(s, solutions), TxoutType::WITNESS_UNKNOWN);
+
+    // Check the static overload with the same single-byte mismatches.
+    BOOST_CHECK(!CScript::IsPayToAnchor(1, {0x4e, 0x00}));
+    BOOST_CHECK(!CScript::IsPayToAnchor(1, {0x00, 0x73}));
 }

 BOOST_AUTO_TEST_CASE(script_standard_ExtractDestination)
diff --git a/src/test/sigopcount_tests.cpp b/src/test/sigopcount_tests.cpp
index a463f43ea8..d0b2c0db87 100644
--- a/src/test/sigopcount_tests.cpp
+++ b/src/test/sigopcount_tests.cpp
@@ -63,6 +63,25 @@ BOOST_AUTO_TEST_CASE(GetSigOpCount)
     CScript scriptSig2;
     scriptSig2 << OP_1 << ToByteVector(dummy) << ToByteVector(dummy) << Serialize(s2);
     BOOST_CHECK_EQUAL(p2sh.GetSigOpCount(scriptSig2), 3U);
+
+    // For non-P2SH outputs, the scriptSig overload counts this script accurately.
+    BOOST_CHECK_EQUAL(s1.GetSigOpCount(scriptSig), 3U);
+
+    // 1-of-1 multisig to verify accurate counting when lastOpcode is OP_1 (boundary of OP_1..OP_16)
+    CScript s_1of1;
+    s_1of1 << OP_1 << ToByteVector(dummy) << OP_1 << OP_CHECKMULTISIG;
+    BOOST_CHECK_EQUAL(s_1of1.GetSigOpCount(true), 1U);
+    BOOST_CHECK_EQUAL(s_1of1.GetSigOpCount(false), 20U);
+
+    // OP_16 is allowed in scriptSig before the serialized redeem script.
+    CScript script_sig_op16;
+    script_sig_op16 << OP_16 << Serialize(s2);
+    BOOST_CHECK_EQUAL(p2sh.GetSigOpCount(script_sig_op16), 3U);
+
+    // OP_NOP is the first opcode above OP_16 and must be rejected.
+    CScript script_sig_nop;
+    script_sig_nop << OP_NOP << Serialize(s2);
+    BOOST_CHECK_EQUAL(p2sh.GetSigOpCount(script_sig_nop), 0U);
 }

 /**
diff --git a/src/test/script_tests.cpp b/src/test/script_tests.cpp
index e6e0744fff..8cef83187b 100644
--- a/src/test/script_tests.cpp
+++ b/src/test/script_tests.cpp
@@ -1628,6 +1628,46 @@ BOOST_AUTO_TEST_CASE(script_HasValidOps)
     BOOST_CHECK(!script.HasValidOps());
     script = ToScript("88acc0"_hex); // Script with undefined opcode
     BOOST_CHECK(!script.HasValidOps());
+    script = CScript() << OP_NOP10; // MAX_OPCODE boundary is valid
+    BOOST_CHECK(script.HasValidOps());
+    script = ToScript("ba"_hex); // MAX_OPCODE + 1 is invalid
+    BOOST_CHECK(!script.HasValidOps());
+}
+
+BOOST_AUTO_TEST_CASE(script_GetOp_truncated)
+{
+    // Test that GetOp returns false on truncated OP_PUSHDATA opcodes
+    opcodetype opcode;
+    std::vector<unsigned char> data;
+
+    // Truncated OP_PUSHDATA1 (missing length byte)
+    CScript s1 = ToScript("4c"_hex);
+    CScript::const_iterator it1 = s1.begin();
+    BOOST_CHECK(!s1.GetOp(it1, opcode, data));
+
+    // Truncated OP_PUSHDATA2 (missing 2nd byte of length)
+    CScript s2 = ToScript("4d01"_hex);
+    CScript::const_iterator it2 = s2.begin();
+    BOOST_CHECK(!s2.GetOp(it2, opcode, data));
+
+    // Truncated OP_PUSHDATA4 (missing remaining length bytes)
+    CScript s4 = ToScript("4e0100"_hex);
+    CScript::const_iterator it4 = s4.begin();
+    BOOST_CHECK(!s4.GetOp(it4, opcode, data));
+}
+
+BOOST_AUTO_TEST_CASE(script_witness_ToString)
+{
+    CScriptWitness wit_empty;
+    BOOST_CHECK_EQUAL(wit_empty.ToString(), "CScriptWitness()");
+
+    CScriptWitness wit_single;
+    wit_single.stack = {{0x01, 0x02}};
+    BOOST_CHECK_EQUAL(wit_single.ToString(), "CScriptWitness(0102)");
+
+    CScriptWitness wit_multi;
+    wit_multi.stack = {{0x01, 0x02}, {0xab, 0xcd}};
+    BOOST_CHECK_EQUAL(wit_multi.ToString(), "CScriptWitness(0102, abcd)");
 }

 BOOST_AUTO_TEST_CASE(bip341_keypath_test_vectors)
diff --git a/src/test/script_segwit_tests.cpp b/src/test/script_segwit_tests.cpp
index fd165e2935..a689d2c2e1 100644
--- a/src/test/script_segwit_tests.cpp
+++ b/src/test/script_segwit_tests.cpp
@@ -67,6 +67,87 @@ BOOST_AUTO_TEST_CASE(IsPayToWitnessScriptHash_Invalid_Pushdata)
     BOOST_CHECK(!CScript(bytes.begin(), bytes.end()).IsPayToWitnessScriptHash());
 }

+BOOST_AUTO_TEST_CASE(IsPayToTaproot_Valid)
+{
+    uint256 dummy;
+    CScript p2tr;
+    p2tr << OP_1 << ToByteVector(dummy);
+    BOOST_CHECK(p2tr.IsPayToTaproot());
+
+    std::vector<unsigned char> bytes = {OP_1, 32};
+    bytes.insert(bytes.end(), 32, 0);
+    BOOST_CHECK(CScript(bytes.begin(), bytes.end()).IsPayToTaproot());
+}
+
+BOOST_AUTO_TEST_CASE(IsPayToTaproot_Invalid_NotOp1)
+{
+    uint256 dummy;
+    CScript notp2tr;
+    notp2tr << OP_0 << ToByteVector(dummy);
+    BOOST_CHECK(!notp2tr.IsPayToTaproot());
+
+    notp2tr.clear();
+    notp2tr << OP_2 << ToByteVector(dummy);
+    BOOST_CHECK(!notp2tr.IsPayToTaproot());
+
+    notp2tr.clear();
+    notp2tr << OP_16 << ToByteVector(dummy);
+    BOOST_CHECK(!notp2tr.IsPayToTaproot());
+}
+
+BOOST_AUTO_TEST_CASE(IsPayToTaproot_Invalid_Size)
+{
+    uint160 dummy160;
+    CScript notp2tr;
+    notp2tr << OP_1 << ToByteVector(dummy160);
+    BOOST_CHECK(!notp2tr.IsPayToTaproot());
+
+    // 31 bytes
+    std::vector<unsigned char> bytes = {OP_1, 31};
+    bytes.insert(bytes.end(), 31, 0);
+    BOOST_CHECK(!CScript(bytes.begin(), bytes.end()).IsPayToTaproot());
+
+    // 33 bytes
+    bytes = {OP_1, 33};
+    bytes.insert(bytes.end(), 33, 0);
+    BOOST_CHECK(!CScript(bytes.begin(), bytes.end()).IsPayToTaproot());
+
+    // 34-byte script that does not match OP_1 0x20
+    bytes = {OP_0, 0x01, 32};
+    bytes.insert(bytes.end(), 31, 0);
+    BOOST_CHECK(!CScript(bytes.begin(), bytes.end()).IsPayToTaproot());
+}
+
+BOOST_AUTO_TEST_CASE(IsPayToTaproot_Invalid_Nop)
+{
+    uint256 dummy;
+    CScript notp2tr;
+    notp2tr << OP_1 << OP_NOP << ToByteVector(dummy);
+    BOOST_CHECK(!notp2tr.IsPayToTaproot());
+}
+
+BOOST_AUTO_TEST_CASE(IsPayToTaproot_Invalid_EmptyScript)
+{
+    CScript notp2tr;
+    BOOST_CHECK(!notp2tr.IsPayToTaproot());
+}
+
+BOOST_AUTO_TEST_CASE(IsPayToTaproot_Invalid_Pushdata)
+{
+    // A script is not P2TR if OP_PUSHDATA is used to push the 32-byte key.
+    std::vector<unsigned char> bytes = {OP_1, OP_PUSHDATA1, 32};
+    bytes.insert(bytes.end(), 32, 0);
+    BOOST_CHECK(!CScript(bytes.begin(), bytes.end()).IsPayToTaproot());
+
+    bytes = {OP_1, OP_PUSHDATA2, 32, 0};
+    bytes.insert(bytes.end(), 32, 0);
+    BOOST_CHECK(!CScript(bytes.begin(), bytes.end()).IsPayToTaproot());
+
+    bytes = {OP_1, OP_PUSHDATA4, 32, 0, 0, 0};
+    bytes.insert(bytes.end(), 32, 0);
+    BOOST_CHECK(!CScript(bytes.begin(), bytes.end()).IsPayToTaproot());
+}
